-- ============================================================
-- Expat Directory seed — 20 real Da Nang businesses
--
-- Sources, per row, recorded in admin_notes:
--   · the business's own website (address, hours, phone, email, photos)
--   · OpenStreetMap, ODbL (coordinates, opening_hours, payment:*, diet:*)
--   · Nominatim reverse geocoding (which ward each coordinate falls in)
--
-- Every row is status='draft' and verified=false. The badge on this site
-- means somebody went there; crawling a website is not that, so nothing
-- here claims it. Amenities are only set where a tag or the business's own
-- page states the fact outright — no row guesses at English level, price
-- band or wifi quality.
--
-- `images` hotlinks each business's own CDN. That is a stopgap: the links
-- break when they redesign, and they are not ours to serve. Replace them
-- with uploads from the admin Directory tab before publishing.
--
-- Re-runnable: upserts on slug, and leaves any row an admin has already
-- edited to published alone.
-- ============================================================

insert into businesses (
  slug, name, category, short_description, description,
  district, district_label, address, lat, lng,
  phone, website, maps_url, email, hours,
  english_level, amenities, payment_methods, images,
  verified, status, admin_notes
) values
('family-medical-practice-da-nang', 'Family Medical Practice Da Nang', 'healthcare', 'International clinic in Hai Chau with English-speaking doctors and a 24/7 ambulance line.', 'Family Medical Practice runs the Da Nang branch of its Vietnam-wide network of international clinics. General practice plus emergency medicine, with a 24/7 medical emergency and ambulance number separate from the clinic line.', 'hai-chau', 'Hai Chau', '96–98 Nguyen Van Linh, Hai Chau, Da Nang', null, null, '+84 236 358 2699', 'https://vietnammedicalpractice.com/locations/da-nang/da-nang', null, 'danang@vietnammedicalpractice.com', 'Mon–Fri 08:00–18:00 · Sat 08:00–17:00 · Sun 08:00–12:00 · Emergency & ambulance 24/7: +84 913 917 303', 'fluent', array['english-staff', 'appointment-needed']::text[], '{}', '{}', false, 'draft', 'Address, hours, phone and email read from the clinic’s own Da Nang location page. No coordinates recorded yet. English level taken from the clinic describing itself as an international practice.'),
('hoan-my-da-nang-hospital', 'Hoan My Da Nang Hospital', 'healthcare', 'Large private hospital on Nguyen Van Linh, part of the Hoan My group.', 'A full private hospital rather than a clinic, on Nguyen Van Linh in Thanh Khe. Hoan My is one of the larger private healthcare groups in Vietnam.', 'thanh-khe', 'Thanh Khe', '291 Nguyen Van Linh, Thanh Khe, Da Nang', 16.0594, 108.20988, null, 'https://hoanmy.com/danang/', 'https://www.google.com/maps/search/?api=1&query=16.0594,108.20988', null, 'Mon–Sat 07:00–11:30, 12:30–16:00 · Sun 07:00–11:30', 'basic', '{}', '{}', array['https://hoanmy.com/wp-content/uploads/2026/11/banner-hmdn-dt.webp']::text[], false, 'draft', 'Hours and address from OpenStreetMap; photo is the hospital building from hoanmy.com/danang. English level not established — confirm on a visit.'),
('tam-tri-general-hospital-da-nang', 'Tam Tri General Hospital Da Nang', 'healthcare', 'Private general hospital in Cam Le, south of the centre.', 'A mid-sized private general hospital on Cach Mang Thang Tam in Cam Le, convenient for the south of the city.', 'cam-le', 'Cam Le', '64 Cach Mang Thang Tam, Cam Le, Da Nang', 16.0229, 108.2142, null, 'https://bvtamtridanang.com.vn', 'https://www.google.com/maps/search/?api=1&query=16.0229,108.2142', null, null, 'basic', '{}', '{}', array['https://bvtamtridanang.com.vn/vnt_upload/weblink/Ynh_bia_web.jpg']::text[], false, 'draft', 'Address and website from OpenStreetMap; photo is the hospital building from its own site. Hours, phone and English level not established.'),
('xliii-specialty-coffee', 'XLIII Specialty Coffee', 'cafe-coworking', 'Specialty roaster on Ngo Thi Si, open 06:30–22:30, outdoor seating and cards accepted.', 'The 43 Factory group’s specialty coffee bar on Ngo Thi Si, a short ride from the An Thuong strip. Long opening hours and a courtyard make it a common daytime work spot.', 'ngu-hanh-son', 'Ngu Hanh Son', '422 Ngo Thi Si, Ngu Hanh Son, Da Nang', 16.04808, 108.24598, '+84 799 343 943', 'https://xliiicoffee.com/location/xliii-coffee-da-nang/', 'https://www.google.com/maps/search/?api=1&query=16.04808,108.24598', null, 'Mon–Sun 06:30–22:30', 'basic', array['outdoor-seating', 'card-accepted']::text[], array['cash', 'card']::text[], array['https://xliiicoffee.com/wp-content/uploads/2023/06/202306060712-43-factory-coffee-roaster-da-nang-vietnam-08.jpeg']::text[], false, 'draft', 'Hours, phone, outdoor seating and card payment all from OpenStreetMap tags. OSM also tags internet_access=wlan — wifi exists, but nobody has tested whether it is fast enough to call it laptop-friendly.'),
('coworking-danang', 'Coworking Danang', 'cafe-coworking', 'Villa-style coworking space on Tran Van Thanh, open Mon–Fri to 22:30.', 'A converted villa with a garden and private meeting rooms, south of the An Thuong strip. Open weekdays only, but late — until 22:30.', 'ngu-hanh-son', 'Ngu Hanh Son', '28 Tran Van Thanh, Ngu Hanh Son, Da Nang', 16.03865, 108.24825, '+84 868 364 415', 'https://coworkingdanang.com/', 'https://www.google.com/maps/search/?api=1&query=16.03865,108.24825', null, 'Mon–Fri 08:00–22:30', 'basic', array['meeting-room']::text[], '{}', array['https://coworkingdanang.com/wp-content/uploads/2024/03/cropped-IMG_9963-scaled-1.jpeg', 'https://coworkingdanang.com/wp-content/uploads/2024/04/IMG_3219-scaled.jpg']::text[], false, 'draft', 'Hours and phone from OpenStreetMap. Meeting room is visible in the second photo from their own site. Day and month rates not confirmed — third-party listings disagree.'),
('ace-coworking-space', 'ACE Coworking Space', 'cafe-coworking', 'Coworking space on Tran Van Du, in the My An area.', 'A coworking space in My An, within walking distance of the beach-side restaurants.', 'ngu-hanh-son', 'Ngu Hanh Son', '12 Tran Van Du, Ngu Hanh Son, Da Nang', 16.04043, 108.24291, null, 'https://acecoworking.vn/', 'https://www.google.com/maps/search/?api=1&query=16.04043,108.24291', null, null, 'basic', '{}', '{}', array['https://acecoworking.vn/wp-content/uploads/2024/05/ace-coworking-danang-home-lead-community@2x.jpg']::text[], false, 'draft', 'Address and website from OpenStreetMap. Opening hours, pricing and phone not published anywhere verifiable.'),
('roots-plant-based-cafe', 'Roots Plant-Based Café', 'cafe-coworking', 'Fully vegan café on Tran Bach Dang, open to 22:45, air-conditioned with outdoor seating.', 'An all-vegan kitchen near the beach end of Tran Bach Dang. OpenStreetMap records it as vegan-only, with gluten-free, dairy-free and sugar-free options alongside.', 'ngu-hanh-son', 'Ngu Hanh Son', '27 Tran Bach Dang, Ngu Hanh Son, Da Nang', 16.04866, 108.24788, '+84 865 528 252', 'https://rootsplantbasedcafe.com/', 'https://www.google.com/maps/search/?api=1&query=16.04866,108.24788', null, 'Mon–Sun 08:30–22:45', 'basic', array['vegan-options', 'air-con', 'outdoor-seating', 'card-accepted']::text[], array['cash', 'card']::text[], array['https://rootsplantbasedcafe.com/wp-content/uploads/roots-web/hero.webp']::text[], false, 'draft', 'Amenities all from explicit OpenStreetMap tags (diet:vegan=only, air_conditioning, outdoor_seating, payment:credit_cards). Their site also shows Ho Chi Minh City branches — the photo used here is the brand hero, not a shot of the Da Nang room.'),
('namaste-omar-indian-restaurant', 'Namaste Omar''s Indian Restaurant', 'restaurants', 'Indian restaurant on Thai Phien in the Hai Chau centre.', 'Indian cooking in the Hai Chau restaurant quarter, a few minutes from the Han river front.', 'hai-chau', 'Hai Chau', '06 Thai Phien, Hai Chau, Da Nang', 16.06494, 108.22387, '+84 917 411 169', 'https://www.namasteomar.com/', 'https://www.google.com/maps/search/?api=1&query=16.06494,108.22387', null, null, 'basic', '{}', '{}', '{}', false, 'draft', 'Address, phone and cuisine from OpenStreetMap. No usable photo on their own site. Hours not published.'),
('le-comptoir-da-nang', 'Le Comptoir', 'restaurants', 'French restaurant on Che Lan Vien, evenings only, takes Visa/Mastercard/PayPal.', 'A small French kitchen on Che Lan Vien, open for dinner service only.', 'ngu-hanh-son', 'Ngu Hanh Son', '16 Che Lan Vien, Ngu Hanh Son, Da Nang', 16.04268, 108.24546, '+84 708 040 560', 'https://lecomptoirdng.com/en/', 'https://www.google.com/maps/search/?api=1&query=16.04268,108.24546', 'lecomptoirdng@gmail.com', 'Mon–Sun 17:00–21:00', 'basic', array['card-accepted']::text[], array['cash', 'card']::text[], array['https://lecomptoirdng.com/wp-content/uploads/2025/02/BOMM0102-4.webp']::text[], false, 'draft', 'Hours, email and card payment from OpenStreetMap tags. Photo is their own interior shot. Site has an /en/ version but staff English level is unconfirmed.'),
('missteak-da-nang', 'Missteak', 'restaurants', 'Steakhouse on Mai Thuc Lan, 11:30–23:00, takes every major card plus contactless.', 'A steakhouse on Mai Thuc Lan with air conditioning, outdoor seating and delivery. The card list in OpenStreetMap is unusually complete — Visa, Mastercard, Amex, JCB, Maestro and contactless.', 'ngu-hanh-son', 'Ngu Hanh Son', '99 Mai Thuc Lan, Ngu Hanh Son, Da Nang', 16.04783, 108.24388, null, 'https://missteak.co/', 'https://www.google.com/maps/search/?api=1&query=16.04783,108.24388', 'hello@missteak.co', 'Mon–Sun 11:30–23:00', 'basic', array['card-accepted', 'air-con', 'outdoor-seating', 'delivery']::text[], array['cash', 'card']::text[], '{}', false, 'draft', 'Amenities from explicit OpenStreetMap payment:* and air_conditioning tags. OSM’s phone field held review-count junk, so no phone is stored. Their site carries only line-art, no photo.'),
('the-new-gym-da-nang', 'The New Gym', 'fitness', '24/7 gym on Hoang Dieu in Hai Chau.', 'Part of a Vietnamese gym chain, on Hoang Dieu in Hai Chau. Open around the clock.', 'hai-chau', 'Hai Chau', '115 Hoang Dieu, Hai Chau, Da Nang', 16.06296, 108.21805, '1900 636 920', 'https://www.thenewgym.vn/', 'https://www.google.com/maps/search/?api=1&query=16.06296,108.21805', null, 'Open 24/7', 'basic', '{}', '{}', '{}', false, 'draft', '24/7 hours and phone from OpenStreetMap. No photo of this branch on the chain site. Membership pricing not confirmed.'),
('spanda-yoga-cafe', 'Spanda Yoga Café', 'fitness', 'Yoga studio with a vegetarian café on An Cu 6, Mon–Sat 08:00–17:00.', 'A yoga studio on the Son Tra side with a vegetarian and vegan café attached.', 'son-tra', 'Son Tra', 'An Cu 6, Son Tra, Da Nang', 16.07494, 108.24178, null, 'https://spandayoga.vn', 'https://www.google.com/maps/search/?api=1&query=16.07494,108.24178', null, 'Mon–Sat 08:00–17:00', 'basic', array['vegan-options']::text[], '{}', array['https://spandayoga.vn/__l5e/assets-v1/91177610-1c7e-4951-bac5-0fd0b66e8c12/spanda-hero.jpg']::text[], false, 'draft', 'Hours and diet tags from OpenStreetMap. Street has no house number in OSM. Class schedule and drop-in price unconfirmed.'),
('singapore-international-school-da-nang', 'Singapore International School @ Da Nang', 'education', 'International school in Phu My An teaching the Cambridge programme.', 'The Da Nang campus of the Singapore International School group, in the Phu My An area of Ngu Hanh Son. Teaches the Cambridge programme in English.', 'ngu-hanh-son', 'Ngu Hanh Son', 'Vung Trung 3 Street, Phu My An New Urban Area, Ngu Hanh Son, Da Nang', null, null, '+84 236 730 1777', 'https://danang.sis.edu.vn/', null, 'enquiry@danang.sis.edu.vn', null, 'fluent', array['english-staff']::text[], '{}', array['https://danang.sis.edu.vn/wp-content/uploads/2026/01/students-homepage.jpg']::text[], false, 'draft', 'Address, phone and email read from the school’s own contact page. No coordinates recorded. Tuition not published on the site.'),
('herbal-spa-an-thuong', 'Herbal Spa — An Thuong', 'beauty', 'Spa on Phan Tu near the An Thuong strip, open daily 09:00–22:30.', 'The An Thuong branch of Herbal Spa, on Phan Tu. The group runs several branches in Da Nang and Hoi An; this row is the Phan Tu one, which has its own hotline and inbox.', 'ngu-hanh-son', 'Ngu Hanh Son', '99-101 Phan Tu, Ngu Hanh Son, Da Nang', null, null, '+84 901 081 188', 'https://www.herbalspa.vn/', null, 'herbalspaanthuong@gmail.com', 'Mon–Sun 09:00–22:30', 'basic', array['appointment-needed']::text[], '{}', array['https://herbalspa.vn/data/album/1000/herbal-spa-an-thuong-da-nang-1774339654.webp']::text[], false, 'draft', 'Branch address, branch hotline, hours and email read from herbalspa.vn’s own contact page. Their site asks guests to book at least 15 minutes ahead, hence appointment-needed. No coordinates recorded.'),
('levenin-spa', 'Levenin Spa', 'beauty', 'Spa in the An Nhon area of Son Tra.', 'A spa on the Son Tra side, in the An Nhon blocks behind the beach road.', 'son-tra', 'Son Tra', null, 16.06933, 108.23619, null, 'https://leveninspa.com/', 'https://www.google.com/maps/search/?api=1&query=16.06933,108.23619', null, null, 'basic', '{}', '{}', array['https://leveninspa.com/wp-content/uploads/2026/08/Levenin.jpg']::text[], false, 'draft', 'OpenStreetMap has coordinates but no street address for this one — the map pin is the only location data. Hours, phone and pricing not published.'),
('my-pet-animal-hospital-24h', 'My Pet''s Animal Hospital (24h)', 'pets', '24-hour veterinary hospital on Ly Thai To.', 'A veterinary hospital on Ly Thai To advertising 24-hour cover, which is rare in the city.', 'thanh-khe', 'Thanh Khe', '22 Ly Thai To, Thanh Khe, Da Nang', 16.0662, 108.20875, '0777 166 466', 'https://mypetclinic.vn/', 'https://www.google.com/maps/search/?api=1&query=16.0662,108.20875', null, null, 'basic', '{}', '{}', '{}', false, 'draft', 'Address and phone from OpenStreetMap; the 24h claim is in their own business name. Their site carries only cartoons and a stock beagle photo, so no image is stored. English level unknown.'),
('nobipet-pet-supermarket', 'Nobipet Pet Supermarket', 'pets', 'Pet supply store on Cu Chinh Lan, 07:30–21:00, takes Visa.', 'A pet supermarket on Cu Chinh Lan stocking food and supplies, with step-free access.', 'thanh-khe', 'Thanh Khe', '169 Cu Chinh Lan, Thanh Khe, Da Nang', 16.06419, 108.18297, '+84 734 057 54', 'https://www.nobipet.vn/', 'https://www.google.com/maps/search/?api=1&query=16.06419,108.18297', 'nobipet@gmail.com', 'Mon–Sun 07:30–21:00', 'basic', array['card-accepted', 'wheelchair-access']::text[], array['cash', 'card']::text[], '{}', false, 'draft', 'Hours, email, wheelchair access and Visa acceptance from OpenStreetMap tags. Their storefront is a KiotViet catalogue, so the only images are of animals for sale — none stored.'),
('aeon-mall-da-nang', 'AEON Mall Da Nang', 'essentials', 'Japanese-run mall on Dien Bien Phu with a full supermarket.', 'The Da Nang branch of the AEON Mall chain, on Dien Bien Phu. Supermarket, food court and the usual mall tenants.', 'thanh-khe', 'Thanh Khe', '46 Dien Bien Phu, Thanh Khe, Da Nang', 16.06654, 108.20428, null, 'https://danangthanhkhe.aeonmall-vietnam.com/vi', 'https://www.google.com/maps/search/?api=1&query=16.06654,108.20428', null, 'Mon–Fri 10:00–22:00 · Sat–Sun 09:00–22:00', 'basic', '{}', '{}', '{}', false, 'draft', 'Hours and address from OpenStreetMap. Their site only serves rotating promotional banners, so no photo is stored.'),
('vincom-plaza-ngo-quyen', 'Vincom Plaza Ngo Quyen', 'essentials', 'Mall on Ngo Quyen, the main shopping centre on the Son Tra side.', 'Vincom’s Ngo Quyen plaza, the main mall east of the river, with a supermarket, cinema and food court.', 'son-tra', 'Son Tra', '910A Ngo Quyen, Son Tra, Da Nang', 16.0714, 108.2303, '+84 934 919 341', 'https://vincom.com.vn/vincom-plaza-ngo-quyen', 'https://www.google.com/maps/search/?api=1&query=16.0714,108.2303', null, 'Mon–Sat 10:00–22:00 · Sun 09:30–22:00', 'basic', '{}', '{}', array['https://statics.vincom.com.vn/vincom-tttm/Vincom-Plaza-Ngo-Quyen-Da-Nang-1787136557.jpg']::text[], false, 'draft', 'Hours and phone from OpenStreetMap; photo is Vincom’s own shot of this plaza.'),
('mm-mega-market-da-nang', 'MM Mega Market Da Nang', 'essentials', 'Wholesale-style supermarket on Cach Mang Thang Tam, 06:00–22:30 daily.', 'A large wholesale-format supermarket in Hoa Cuong, useful for bulk and imported goods. Opens at 06:00 and runs to 22:30 every day.', 'hai-chau', 'Hai Chau', '5 Cach Mang Thang Tam, Hai Chau, Da Nang', 16.02475, 108.22029, null, 'https://www.mmvietnam.com/', 'https://www.google.com/maps/search/?api=1&query=16.02475,108.22029', null, 'Mon–Sun 06:00–22:30', 'basic', '{}', '{}', '{}', false, 'draft', 'Hours and address from OpenStreetMap. Chain site has no photo of this branch.')
on conflict (slug) do update set
  name              = excluded.name,
  category          = excluded.category,
  short_description = excluded.short_description,
  description       = excluded.description,
  district          = excluded.district,
  district_label    = excluded.district_label,
  address           = excluded.address,
  lat               = excluded.lat,
  lng               = excluded.lng,
  phone             = excluded.phone,
  website           = excluded.website,
  maps_url          = excluded.maps_url,
  email             = excluded.email,
  hours             = excluded.hours,
  english_level     = excluded.english_level,
  amenities         = excluded.amenities,
  payment_methods   = excluded.payment_methods,
  images            = excluded.images,
  admin_notes       = excluded.admin_notes
where businesses.status = 'draft';
